import { JSDOM } from "jsdom";
import { afterEach, describe, expect, it, vi } from "vitest";
import { BROWSER_INTERACTION_BINDING } from "./browser-interaction-events.js";
import { createBrowserInteractionScript } from "./browser-interaction-script.js";
import { BROWSER_INTERACTION_SOURCE } from "./browser-interaction-sanitize.js";

function createDom(html: string) {
  const dom = new JSDOM(html, {
    url: "https://example.com/form",
    runScripts: "outside-only",
    pretendToBeVisual: true,
  });
  const binding = vi.fn();
  (dom.window as any)[BROWSER_INTERACTION_BINDING] = binding;
  dom.window.eval(createBrowserInteractionScript(BROWSER_INTERACTION_BINDING));
  return { dom, binding };
}

function payloads(binding: ReturnType<typeof vi.fn>) {
  return binding.mock.calls.map(([payload]) => JSON.parse(payload as string));
}

afterEach(() => {
  vi.restoreAllMocks();
});

describe("browser interaction injected script", () => {
  it("emits click and doubleClick payloads through the binding", () => {
    const { dom, binding } = createDom(`<button id="save">Save</button>`);
    const button = dom.window.document.querySelector("button")!;

    button.dispatchEvent(
      new dom.window.MouseEvent("click", {
        bubbles: true,
        composed: true,
        clientX: 10,
        clientY: 20,
        detail: 1,
        button: 0,
      }),
    );
    button.dispatchEvent(
      new dom.window.MouseEvent("click", {
        bubbles: true,
        composed: true,
        clientX: 11,
        clientY: 21,
        detail: 2,
        button: 0,
      }),
    );

    expect(payloads(binding).map((payload) => payload.interaction.action)).toEqual([
      "click",
      "doubleClick",
    ]);
    expect(payloads(binding)[0]).toMatchObject({
      source: BROWSER_INTERACTION_SOURCE,
      interaction: {
        pointer: { x: 10, y: 20, button: 0, clickCount: 1 },
        target: {
          tagName: "button",
          role: "button",
          text: "Save",
        },
      },
    });
    dom.window.close();
  });

  it("omits input text by default while preserving length and redaction metadata", () => {
    const { dom, binding } = createDom(`
      <input id="email" name="email" />
      <input id="password" type="password" />
      <input id="otp" autocomplete="one-time-code" />
    `);
    const email = dom.window.document.querySelector<HTMLInputElement>("#email")!;
    const password = dom.window.document.querySelector<HTMLInputElement>("#password")!;
    const otp = dom.window.document.querySelector<HTMLInputElement>("#otp")!;

    email.value = "user@example.com";
    password.value = "super-secret";
    otp.value = "123456";

    email.dispatchEvent(new dom.window.Event("input", { bubbles: true, composed: true }));
    password.dispatchEvent(new dom.window.Event("input", { bubbles: true, composed: true }));
    otp.dispatchEvent(new dom.window.Event("input", { bubbles: true, composed: true }));

    const interactions = payloads(binding).map((payload) => payload.interaction);
    expect(interactions[0].value).toMatchObject({
      inputType: "text",
      valueLength: "user@example.com".length,
    });
    expect(interactions[0].value.text).toBeUndefined();
    expect(interactions[1].value).toMatchObject({
      inputType: "password",
      valueLength: "super-secret".length,
      redacted: true,
    });
    expect(interactions[1].value.text).toBeUndefined();
    expect(interactions[2].value).toMatchObject({
      inputType: "text",
      valueLength: "123456".length,
      redacted: true,
    });
    expect(interactions[2].value.text).toBeUndefined();
    dom.window.close();
  });

  it("redacts sensitive inputs identified by test attributes", () => {
    const { dom, binding } = createDom(`
      <input data-test="credit-card-number" />
      <input data-cy="password" />
    `);
    const creditCard = dom.window.document.querySelector<HTMLInputElement>("[data-test]")!;
    const password = dom.window.document.querySelector<HTMLInputElement>("[data-cy]")!;

    creditCard.value = "4111111111111111";
    password.value = "secret-from-data-cy";

    creditCard.dispatchEvent(new dom.window.Event("input", { bubbles: true, composed: true }));
    password.dispatchEvent(new dom.window.Event("input", { bubbles: true, composed: true }));

    const interactions = payloads(binding).map((payload) => payload.interaction);
    expect(interactions[0].value).toMatchObject({
      valueLength: "4111111111111111".length,
      redacted: true,
    });
    expect(interactions[0].value.text).toBeUndefined();
    expect(interactions[1].value).toMatchObject({
      valueLength: "secret-from-data-cy".length,
      redacted: true,
    });
    expect(interactions[1].value.text).toBeUndefined();
    dom.window.close();
  });

  it("uses the matched test attribute when building selectors", () => {
    const { dom, binding } = createDom(`<button data-cy="save">Save</button>`);
    const button = dom.window.document.querySelector("button")!;

    button.dispatchEvent(
      new dom.window.MouseEvent("click", {
        bubbles: true,
        composed: true,
        detail: 1,
      }),
    );

    const [payload] = payloads(binding);
    expect(payload.interaction.target.attributes.testId).toBe("save");
    expect(payload.interaction.target.selector.testId).toBe('[data-cy="save"]');
    expect(payload.interaction.target.selector.css).toContain('[data-cy="save"]');
    dom.window.close();
  });

  it("does not include direct text from editable targets", () => {
    const { dom, binding } = createDom(`<div contenteditable="true">typed private note</div>`);
    const editor = dom.window.document.querySelector("div")!;

    editor.dispatchEvent(
      new dom.window.MouseEvent("click", {
        bubbles: true,
        composed: true,
        detail: 1,
      }),
    );

    const [payload] = payloads(binding);
    expect(payload.interaction.target.tagName).toBe("div");
    expect(payload.interaction.target.text).toBeUndefined();
    expect(payload.interaction.target.accessibleName).toBeUndefined();
    dom.window.close();
  });

  it("records non-printable key presses but skips printable input typing", () => {
    const { dom, binding } = createDom(`<input id="query" />`);
    const input = dom.window.document.querySelector<HTMLInputElement>("#query")!;

    input.dispatchEvent(
      new dom.window.KeyboardEvent("keydown", {
        bubbles: true,
        composed: true,
        key: "a",
        code: "KeyA",
      }),
    );
    input.dispatchEvent(
      new dom.window.KeyboardEvent("keydown", {
        bubbles: true,
        composed: true,
        key: "Enter",
        code: "Enter",
      }),
    );

    const interactions = payloads(binding).map((payload) => payload.interaction);
    expect(interactions).toHaveLength(1);
    expect(interactions[0]).toMatchObject({
      action: "keyPress",
      keyboard: { key: "Enter", code: "Enter" },
    });
    dom.window.close();
  });

  it("emits drag and suppresses the following click", () => {
    const { dom, binding } = createDom(`<button id="drag">Drag</button>`);
    const button = dom.window.document.querySelector("button")!;
    const now = vi.spyOn(dom.window.Date, "now");
    now.mockReturnValueOnce(1_000);
    now.mockReturnValueOnce(1_600);
    now.mockReturnValueOnce(1_601);

    button.dispatchEvent(
      new dom.window.MouseEvent("mousedown", {
        bubbles: true,
        composed: true,
        clientX: 0,
        clientY: 0,
        button: 0,
      }),
    );
    button.dispatchEvent(
      new dom.window.MouseEvent("mouseup", {
        bubbles: true,
        composed: true,
        clientX: 20,
        clientY: 0,
        button: 0,
      }),
    );
    button.dispatchEvent(
      new dom.window.MouseEvent("click", {
        bubbles: true,
        composed: true,
        clientX: 20,
        clientY: 0,
        detail: 1,
        button: 0,
      }),
    );

    const interactions = payloads(binding).map((payload) => payload.interaction);
    expect(interactions).toHaveLength(1);
    expect(interactions[0]).toMatchObject({
      action: "drag",
      pointer: { startX: 0, startY: 0, endX: 20, endY: 0, button: 0 },
    });
    dom.window.close();
  });

  it("debounces scroll events", async () => {
    const { dom, binding } = createDom(`<main>content</main>`);
    Object.defineProperty(dom.window, "scrollX", { value: 12, configurable: true });
    Object.defineProperty(dom.window, "scrollY", { value: 34, configurable: true });

    dom.window.document.dispatchEvent(new dom.window.Event("scroll"));
    dom.window.document.dispatchEvent(new dom.window.Event("scroll"));
    expect(binding).not.toHaveBeenCalled();

    await new Promise((resolve) => dom.window.setTimeout(resolve, 250));

    const interactions = payloads(binding).map((payload) => payload.interaction);
    expect(interactions).toHaveLength(1);
    expect(interactions[0]).toMatchObject({
      action: "scroll",
      pointer: { x: 12, y: 34 },
    });
    dom.window.close();
  });

  it("captures scrolls from nested scroll containers", async () => {
    const { dom, binding } = createDom(`<main id="scrollable">content</main>`);
    const scrollable = dom.window.document.querySelector("#scrollable")!;

    scrollable.dispatchEvent(new dom.window.Event("scroll"));

    await new Promise((resolve) => dom.window.setTimeout(resolve, 250));

    const interactions = payloads(binding).map((payload) => payload.interaction);
    expect(interactions).toHaveLength(1);
    expect(interactions[0]).toMatchObject({ action: "scroll" });
    dom.window.close();
  });

  it("does not install duplicate listeners", () => {
    const { dom, binding } = createDom(`<button>Save</button>`);
    const button = dom.window.document.querySelector("button")!;
    dom.window.eval(createBrowserInteractionScript(BROWSER_INTERACTION_BINDING));

    button.dispatchEvent(
      new dom.window.MouseEvent("click", {
        bubbles: true,
        composed: true,
        detail: 1,
      }),
    );

    expect(payloads(binding)).toHaveLength(1);
    dom.window.close();
  });
});

import { EventEmitter } from "events";
import { TargetType } from "puppeteer-core";
import { describe, expect, it } from "vitest";
import { BrowserEventType } from "../../../types/enums.js";
import type { BrowserLogger } from "./browser-logger.js";
import { attachCDPEvents } from "./cdp-events.js";
import {
  attachBrowserInteractionEvents,
  BROWSER_INTERACTION_BINDING,
  BROWSER_INTERACTION_WORLD,
} from "./browser-interaction-events.js";
import { BROWSER_INTERACTION_SOURCE } from "./browser-interaction-sanitize.js";
import type { BrowserEventUnion } from "./types.js";

class FakeSession extends EventEmitter {
  calls: Array<{ method: string; params?: any }> = [];
  failRunImmediately = false;

  id() {
    return "fake-session";
  }

  async send(method: string, params?: any) {
    this.calls.push({ method, params });
    if (
      this.failRunImmediately &&
      method === "Page.addScriptToEvaluateOnNewDocument" &&
      params?.runImmediately === true
    ) {
      throw new Error("runImmediately not supported");
    }
    return {};
  }
}

class FakePage extends EventEmitter {
  currentUrl = "about:blank";

  url() {
    return this.currentUrl;
  }
}

function createLogger() {
  const records: BrowserEventUnion[] = [];
  const logger: BrowserLogger = {
    record: (event) => records.push(event),
    resetContext: () => {},
    setContext: () => {},
    getContext: () => ({}),
  };
  return { logger, records };
}

describe("browser interaction CDP attachment", () => {
  it("adds the runtime binding and page script", async () => {
    const session = new FakeSession();
    const page = new FakePage();
    const { logger } = createLogger();

    await attachBrowserInteractionEvents(
      session as any,
      page as any,
      logger,
      TargetType.PAGE,
      "page-1",
    );

    expect(session.calls[0]).toEqual({
      method: "Runtime.addBinding",
      params: {
        name: BROWSER_INTERACTION_BINDING,
        executionContextName: BROWSER_INTERACTION_WORLD,
      },
    });
    expect(session.calls[1]).toMatchObject({
      method: "Page.addScriptToEvaluateOnNewDocument",
      params: {
        worldName: BROWSER_INTERACTION_WORLD,
        runImmediately: true,
      },
    });
    expect(session.calls[1].params.source).toContain(BROWSER_INTERACTION_BINDING);
  });

  it("falls back when runImmediately is not supported", async () => {
    const session = new FakeSession();
    session.failRunImmediately = true;
    const page = new FakePage();
    const { logger } = createLogger();

    await attachBrowserInteractionEvents(
      session as any,
      page as any,
      logger,
      TargetType.PAGE,
      "page-1",
    );

    expect(session.calls).toEqual([
      expect.objectContaining({ method: "Runtime.addBinding" }),
      expect.objectContaining({
        method: "Page.addScriptToEvaluateOnNewDocument",
        params: expect.objectContaining({ runImmediately: true }),
      }),
      expect.objectContaining({
        method: "Page.addScriptToEvaluateOnNewDocument",
        params: expect.not.objectContaining({ runImmediately: true }),
      }),
    ]);
  });

  it("records sanitized binding payloads as browser interactions", async () => {
    const session = new FakeSession();
    const page = new FakePage();
    const { logger, records } = createLogger();

    await attachBrowserInteractionEvents(
      session as any,
      page as any,
      logger,
      TargetType.PAGE,
      "page-1",
    );
    records.length = 0;

    session.emit("Runtime.bindingCalled", {
      name: BROWSER_INTERACTION_BINDING,
      payload: JSON.stringify({
        source: BROWSER_INTERACTION_SOURCE,
        timestamp: "2026-05-22T00:00:00.000Z",
        interaction: {
          action: "click",
          eventType: "click",
          pointer: { x: 1, y: 2, button: 0, clickCount: 1 },
          page: { url: "https://example.com" },
        },
      }),
    });

    expect(records).toHaveLength(1);
    expect(records[0]).toMatchObject({
      type: BrowserEventType.BrowserInteraction,
      timestamp: "2026-05-22T00:00:00.000Z",
      pageId: "page-1",
      interaction: {
        action: "click",
        pointer: { x: 1, y: 2, button: 0, clickCount: 1 },
        page: { url: "https://example.com" },
      },
    });
  });

  it("records only main-frame navigation interactions", async () => {
    const session = new FakeSession();
    const page = new FakePage();
    page.currentUrl = "https://initial.example";
    const { logger, records } = createLogger();

    await attachBrowserInteractionEvents(
      session as any,
      page as any,
      logger,
      TargetType.PAGE,
      "page-1",
    );
    records.length = 0;

    page.emit("framenavigated", {
      parentFrame: () => ({}),
      url: () => "https://iframe.example",
    });
    page.emit("framenavigated", {
      parentFrame: () => null,
      url: () => "https://main.example",
    });

    expect(records).toHaveLength(1);
    expect(records[0]).toMatchObject({
      type: BrowserEventType.BrowserInteraction,
      interaction: {
        action: "navigate",
        navigation: { url: "https://main.example" },
      },
    });
  });

  it("does not duplicate browser interaction binding calls as raw CDP events", () => {
    const session = new FakeSession();
    const { logger, records } = createLogger();

    attachCDPEvents(session as any, logger);
    session.emit("event", {
      method: "Runtime.bindingCalled",
      params: { name: BROWSER_INTERACTION_BINDING },
    });
    session.emit("event", {
      method: "Runtime.bindingCalled",
      params: { name: "otherBinding" },
    });

    expect(records).toHaveLength(1);
    expect(records[0]).toMatchObject({
      type: BrowserEventType.CDPEvent,
      cdp: { name: "Runtime.bindingCalled", params: { name: "otherBinding" } },
    });
  });
});

import { describe, expect, it } from "vitest";
import {
  MAX_BROWSER_INTERACTION_TEXT_LENGTH,
  sanitizeInteractionPayload,
  truncateBrowserInteractionText,
} from "./browser-interaction-sanitize.js";

describe("browser interaction sanitizer", () => {
  it("drops malformed and unknown interaction payloads", () => {
    expect(sanitizeInteractionPayload(null)).toBeNull();
    expect(sanitizeInteractionPayload({ interaction: null })).toBeNull();
    expect(
      sanitizeInteractionPayload({
        interaction: { action: "hover", eventType: "mouseover" },
      }),
    ).toBeNull();
    expect(
      sanitizeInteractionPayload({
        interaction: { action: "click", eventType: 123 },
      }),
    ).toBeNull();
  });

  it("normalizes and truncates text fields", () => {
    const longText = "x".repeat(MAX_BROWSER_INTERACTION_TEXT_LENGTH + 20);
    const interaction = sanitizeInteractionPayload({
      interaction: {
        action: "click",
        eventType: "click",
        target: {
          accessibleName: `  ${longText}\n\n`,
          text: "  primary   button  ",
        },
      },
    });

    expect(interaction?.target?.accessibleName).toHaveLength(MAX_BROWSER_INTERACTION_TEXT_LENGTH);
    expect(interaction?.target?.accessibleName?.endsWith("...")).toBe(true);
    expect(interaction?.target?.text).toBe("primary button");
  });

  it("keeps only finite numeric pointer values", () => {
    const interaction = sanitizeInteractionPayload({
      interaction: {
        action: "click",
        eventType: "click",
        pointer: {
          x: 12,
          y: Number.NaN,
          button: Number.POSITIVE_INFINITY,
          clickCount: 1,
        },
      },
    });

    expect(interaction?.pointer).toBeUndefined();
  });

  it("preserves drag pointer shape and drag end metadata", () => {
    const interaction = sanitizeInteractionPayload({
      interaction: {
        action: "drag",
        eventType: "drag",
        endTimestamp: "2026-05-22T00:00:01.000Z",
        pointer: {
          startX: 1,
          startY: 2,
          endX: 10,
          endY: 20,
          button: 0,
        },
        endTarget: { tagName: "button" },
      },
    });

    expect(interaction?.pointer).toEqual({
      startX: 1,
      startY: 2,
      endX: 10,
      endY: 20,
      button: 0,
    });
    expect(interaction?.endTimestamp).toBe("2026-05-22T00:00:01.000Z");
    expect(interaction?.endTarget?.tagName).toBe("button");
  });

  it("sanitizes value and page metadata", () => {
    const interaction = sanitizeInteractionPayload({
      interaction: {
        action: "input",
        eventType: "input",
        value: {
          inputType: "text",
          valueLength: 8,
          text: " hello ",
          redacted: false,
          checked: true,
        },
        page: {
          url: " https://example.com/form ",
          title: 123,
        },
      },
    });

    expect(interaction?.value).toEqual({
      inputType: "text",
      valueLength: 8,
      text: "hello",
      redacted: undefined,
      checked: true,
    });
    expect(interaction?.page).toEqual({
      url: "https://example.com/form",
      title: undefined,
    });
  });

  it("exposes text truncation for direct unit coverage", () => {
    expect(truncateBrowserInteractionText("  a\n b\t c  ")).toBe("a b c");
    expect(truncateBrowserInteractionText("   ")).toBeUndefined();
    expect(truncateBrowserInteractionText(1)).toBeUndefined();
  });
});

import { describe, it, expect } from "vitest";
import { isSimilarConfig } from "./validation.js";
import type { BrowserLauncherOptions } from "../../../types/browser.js";

// Minimal valid config — only required field is `options`
const base: BrowserLauncherOptions = { options: {} };

const withCerts = (certs: string[]): BrowserLauncherOptions => ({
  ...base,
  caCertificates: certs,
});

describe("isSimilarConfig", () => {
  describe("missing configs", () => {
    it("returns false when both configs are undefined", async () => {
      expect(await isSimilarConfig(undefined, undefined)).toBe(false);
    });

    it("returns false when current is undefined", async () => {
      expect(await isSimilarConfig(undefined, base)).toBe(false);
    });

    it("returns false when next is undefined", async () => {
      expect(await isSimilarConfig(base, undefined)).toBe(false);
    });
  });

  describe("caCertificates", () => {
    const certA = "-----BEGIN CERTIFICATE-----\nMIIBcert-a\n-----END CERTIFICATE-----";
    const certB = "-----BEGIN CERTIFICATE-----\nMIIBcert-b\n-----END CERTIFICATE-----";

    it("treats both undefined as similar", async () => {
      expect(await isSimilarConfig(base, base)).toBe(true);
    });

    it("treats both empty arrays as similar", async () => {
      expect(await isSimilarConfig(withCerts([]), withCerts([]))).toBe(true);
    });

    it("treats undefined and empty array as similar", async () => {
      expect(await isSimilarConfig(base, withCerts([]))).toBe(true);
      expect(await isSimilarConfig(withCerts([]), base)).toBe(true);
    });

    it("treats identical cert arrays as similar", async () => {
      expect(await isSimilarConfig(withCerts([certA]), withCerts([certA]))).toBe(true);
    });

    it("treats same certs in different order as similar", async () => {
      expect(await isSimilarConfig(withCerts([certA, certB]), withCerts([certB, certA]))).toBe(
        true,
      );
    });

    it("treats different certs as not similar", async () => {
      expect(await isSimilarConfig(withCerts([certA]), withCerts([certB]))).toBe(false);
    });

    it("treats a cert being added as not similar", async () => {
      expect(await isSimilarConfig(base, withCerts([certA]))).toBe(false);
      expect(await isSimilarConfig(withCerts([certA]), base)).toBe(false);
    });

    it("treats a cert being removed as not similar", async () => {
      expect(await isSimilarConfig(withCerts([certA, certB]), withCerts([certA]))).toBe(false);
    });

    it("treats a subset of certs as not similar", async () => {
      expect(await isSimilarConfig(withCerts([certA]), withCerts([certA, certB]))).toBe(false);
    });
  });

  describe("existing fields are unaffected", () => {
    it("headless mismatch is not similar", async () => {
      const headless: BrowserLauncherOptions = { options: { headless: true } };
      const headful: BrowserLauncherOptions = { options: { headless: false } };
      expect(await isSimilarConfig(headless, headful)).toBe(false);
    });

    it("proxy mismatch is not similar", async () => {
      const a: BrowserLauncherOptions = { options: { proxyUrl: "http://proxy-a:3128" } };
      const b: BrowserLauncherOptions = { options: { proxyUrl: "http://proxy-b:3128" } };
      expect(await isSimilarConfig(a, b)).toBe(false);
    });

    it("userAgent mismatch is not similar", async () => {
      const a: BrowserLauncherOptions = { ...base, userAgent: "Mozilla/5.0 (agent-a)" };
      const b: BrowserLauncherOptions = { ...base, userAgent: "Mozilla/5.0 (agent-b)" };
      expect(await isSimilarConfig(a, b)).toBe(false);
    });

    it("matching full config with caCertificates is similar", async () => {
      const certA = "-----BEGIN CERTIFICATE-----\nMIIBcert-a\n-----END CERTIFICATE-----";
      const config: BrowserLauncherOptions = {
        options: { headless: true, proxyUrl: "http://proxy:3128" },
        userAgent: "Mozilla/5.0",
        blockAds: true,
        caCertificates: [certA],
      };
      expect(await isSimilarConfig(config, { ...config })).toBe(true);
    });
  });
});

import {
  BROWSER_INTERACTION_SOURCE,
  MAX_BROWSER_INTERACTION_TEXT_LENGTH,
} from "./browser-interaction-sanitize.js";

export interface BrowserInteractionLoggerOptions {
  bindingName: string;
  source: string;
  maxTextLength: number;
}

export function installBrowserInteractionLogger(options: BrowserInteractionLoggerOptions): void {
  const { bindingName, source, maxTextLength } = options;
  const steelWindow = window as unknown as Window & {
    __steelBrowserInteractionInstalled?: boolean;
    [key: string]: unknown;
  };

  if (steelWindow.__steelBrowserInteractionInstalled) return;
  Object.defineProperty(steelWindow, "__steelBrowserInteractionInstalled", {
    value: true,
    configurable: false,
    enumerable: false,
  });

  const compact = (value: unknown) => {
    if (typeof value !== "string") return undefined;
    const normalized = value.replace(/\s+/g, " ").trim();
    if (!normalized) return undefined;
    return normalized.length > maxTextLength
      ? normalized.slice(0, maxTextLength - 3) + "..."
      : normalized;
  };

  const directText = (element: unknown) => {
    if (!(element instanceof Element)) return undefined;

    let value = "";
    for (const node of element.childNodes) {
      if (node.nodeType !== Node.TEXT_NODE) continue;
      const text = node.textContent || "";
      if (!/\S/.test(text)) continue;

      const remaining = maxTextLength - value.length;
      if (remaining <= 0) break;

      value += " " + text.slice(0, remaining);
    }

    return compact(value);
  };

  const attr = (element: unknown, name: string) => {
    if (!(element instanceof Element)) return undefined;
    return compact(element.getAttribute(name) || undefined);
  };

  const cssEscape = (value: string) => {
    if (window.CSS && typeof window.CSS.escape === "function") {
      return window.CSS.escape(value);
    }
    return String(value).replace(/[^a-zA-Z0-9_-]/g, "\\$&");
  };

  const testAttributeNames = ["data-testid", "data-test", "data-cy"];

  const testAttribute = (element: Element) => {
    for (const name of testAttributeNames) {
      const value = attr(element, name);
      if (value) return { name, value };
    }
    return undefined;
  };

  const testAttributeSelector = (testAttr: { name: string; value: string }) =>
    "[" + testAttr.name + '="' + cssEscape(testAttr.value) + '"]';

  const implicitRole = (element: Element) => {
    const tagName = element.tagName?.toLowerCase();
    if (tagName === "button") return "button";
    if (tagName === "a" && element.hasAttribute("href")) return "link";
    if (tagName === "input") {
      const type = (element.getAttribute("type") || "text").toLowerCase();
      if (type === "checkbox") return "checkbox";
      if (type === "radio") return "radio";
      if (type === "button" || type === "submit" || type === "reset") return "button";
      return "textbox";
    }
    if (tagName === "textarea") return "textbox";
    if (tagName === "select") return "combobox";
    if (tagName === "summary") return "button";
    return undefined;
  };

  const associatedLabel = (element: Element) => {
    if (element instanceof HTMLInputElement && element.labels && element.labels.length > 0) {
      return compact(
        Array.from(element.labels)
          .map((label) => label.textContent || "")
          .join(" "),
      );
    }
    const id = (element as HTMLElement).id;
    if (!id) return undefined;
    try {
      const label = document.querySelector('label[for="' + cssEscape(id) + '"]');
      return compact(label?.textContent || undefined);
    } catch {
      return undefined;
    }
  };

  const labelledByText = (element: Element) => {
    const ids = attr(element, "aria-labelledby");
    if (!ids) return undefined;
    return compact(
      ids
        .split(/\s+/)
        .map((id) => document.getElementById(id)?.textContent || "")
        .join(" "),
    );
  };

  const isEditableElement = (element: Element) =>
    element instanceof HTMLInputElement ||
    element instanceof HTMLTextAreaElement ||
    element instanceof HTMLSelectElement ||
    (element instanceof HTMLElement &&
      (element.isContentEditable || element.hasAttribute("contenteditable")));

  const accessibleName = (element: Element) =>
    attr(element, "aria-label") ||
    labelledByText(element) ||
    associatedLabel(element) ||
    attr(element, "alt") ||
    attr(element, "title") ||
    attr(element, "placeholder") ||
    (isEditableElement(element) ? undefined : directText(element));

  const isMeaningfulElement = (element: unknown) => {
    if (!(element instanceof Element)) return false;
    const tagName = element.tagName.toLowerCase();
    return (
      ["button", "a", "input", "textarea", "select", "summary", "label"].includes(tagName) ||
      element.hasAttribute("role") ||
      element.hasAttribute("aria-label") ||
      element.hasAttribute("data-testid") ||
      element.hasAttribute("data-test") ||
      element.hasAttribute("data-cy") ||
      element.hasAttribute("contenteditable")
    );
  };

  const meaningfulElementFromPath = (event: Event) => {
    const path = typeof event.composedPath === "function" ? event.composedPath() : [];
    for (const item of path) {
      if (isMeaningfulElement(item)) return item as Element;
    }
    return event.target instanceof Element ? event.target : undefined;
  };

  const cssPath = (element: Element) => {
    const parts: string[] = [];
    let current: Element | null = element;
    while (current && current.nodeType === Node.ELEMENT_NODE && parts.length < 5) {
      const tagName = current.tagName.toLowerCase();
      const id = current.getAttribute("id");
      if (id) {
        parts.unshift(tagName + "#" + cssEscape(id));
        break;
      }
      let part = tagName;
      const testAttr = testAttribute(current);
      if (testAttr) {
        part += testAttributeSelector(testAttr);
      } else {
        const parent = current.parentElement;
        if (parent) {
          const siblings = Array.from(parent.children).filter(
            (child) => child.tagName === current?.tagName,
          );
          if (siblings.length > 1) part += ":nth-of-type(" + (siblings.indexOf(current) + 1) + ")";
        }
      }
      parts.unshift(part);
      current = current.parentElement;
    }
    return compact(parts.join(" > "));
  };

  const selectorCandidates = (element: Element) => {
    const id = attr(element, "id");
    const testAttr = testAttribute(element);
    const name = attr(element, "name");
    const ariaLabel = attr(element, "aria-label");
    return {
      id: id ? "#" + cssEscape(id) : undefined,
      testId: testAttr ? testAttributeSelector(testAttr) : undefined,
      name: name ? '[name="' + cssEscape(name) + '"]' : undefined,
      aria: ariaLabel ? '[aria-label="' + cssEscape(ariaLabel) + '"]' : undefined,
      css: cssPath(element),
    };
  };

  const targetSnapshot = (event: Event) => {
    const element = meaningfulElementFromPath(event);
    if (!(element instanceof Element)) return undefined;
    const rect = element.getBoundingClientRect();
    const testId =
      attr(element, "data-testid") || attr(element, "data-test") || attr(element, "data-cy");
    return {
      tagName: compact(element.tagName.toLowerCase()),
      role: attr(element, "role") || implicitRole(element),
      accessibleName: accessibleName(element),
      text: isEditableElement(element) ? undefined : directText(element),
      attributes: {
        id: attr(element, "id"),
        name: attr(element, "name"),
        type: attr(element, "type"),
        href: attr(element, "href"),
        ariaLabel: attr(element, "aria-label"),
        placeholder: attr(element, "placeholder"),
        title: attr(element, "title"),
        testId,
      },
      selector: selectorCandidates(element),
      boundingBox: {
        x: rect.x,
        y: rect.y,
        width: rect.width,
        height: rect.height,
      },
    };
  };

  const sensitiveKeywords = [
    "password",
    "passwd",
    "pwd",
    "secret",
    "card",
    "cardnumber",
    "cc-number",
    "cc-csc",
    "cc-exp",
    "cvv",
    "cvc",
    "ssn",
    "social",
    "otp",
    "tax",
  ];

  const isSensitiveField = (target: unknown) => {
    if (!(target instanceof Element)) return false;
    if (target instanceof HTMLInputElement) {
      const type = (target.type || "").toLowerCase();
      if (type === "password") return true;
      const autocomplete = (target.getAttribute("autocomplete") || "").toLowerCase();
      if (autocomplete.startsWith("cc-")) return true;
      if (autocomplete === "current-password" || autocomplete === "new-password") return true;
      if (autocomplete === "one-time-code") return true;
    }
    const haystacks = [
      target.getAttribute("name") || "",
      (target as HTMLElement).id || "",
      target.getAttribute("aria-label") || "",
      target.getAttribute("placeholder") || "",
      ...testAttributeNames.map((name) => target.getAttribute(name) || ""),
    ].map((s) => s.toLowerCase());
    return haystacks.some((s) => sensitiveKeywords.some((kw) => s.includes(kw)));
  };

  const valueSnapshot = (event: Event) => {
    const target = event.target;
    if (
      !(
        target instanceof HTMLInputElement ||
        target instanceof HTMLTextAreaElement ||
        target instanceof HTMLSelectElement
      )
    ) {
      return undefined;
    }
    const inputType =
      target instanceof HTMLInputElement ? target.type : target.tagName.toLowerCase();
    const rawValue = typeof target.value === "string" ? target.value : undefined;
    const valueLength = typeof rawValue === "string" ? rawValue.length : undefined;
    const sensitive = isSensitiveField(target);
    return {
      inputType,
      valueLength,
      text: undefined,
      redacted: sensitive || undefined,
      checked:
        target instanceof HTMLInputElement && ["checkbox", "radio"].includes(target.type)
          ? target.checked
          : undefined,
    };
  };

  const emitPayload = (payload: object) => {
    const binding = steelWindow[bindingName];
    if (typeof binding !== "function") return;
    try {
      binding(JSON.stringify(payload));
    } catch {
      // Logging must never affect the page.
    }
  };

  const send = (event: Event, interaction: Record<string, unknown>) => {
    emitPayload({
      source,
      timestamp: new Date().toISOString(),
      interaction: {
        ...interaction,
        target: targetSnapshot(event),
        page: {
          url: location.href,
          title: document.title,
        },
      },
    });
  };

  // Drag detection. mousedown->mouseup with duration > 500ms (sync with
  // apps/live/src/viewer/input/input-interactions.ts dragHoldThresholdMs) or
  // movement > 8px is treated as a drag; otherwise the browser's own click
  // event fires the normal click/doubleClick path.
  const dragHoldThresholdMs = 500;
  const dragMoveThresholdPx = 8;
  let dragState: {
    startX: number;
    startY: number;
    startTime: number;
    startTargetSnapshot?: ReturnType<typeof targetSnapshot>;
    button: number;
  } | null = null;
  let suppressClickUntil = 0;

  document.addEventListener(
    "mousedown",
    (event) => {
      const mouseEvent = event as MouseEvent;
      dragState = {
        startX: mouseEvent.clientX,
        startY: mouseEvent.clientY,
        startTime: Date.now(),
        startTargetSnapshot: targetSnapshot(mouseEvent),
        button: mouseEvent.button,
      };
    },
    { capture: true, passive: true },
  );

  document.addEventListener(
    "mouseup",
    (event) => {
      const mouseEvent = event as MouseEvent;
      const current = dragState;
      dragState = null;
      if (!current || current.button !== mouseEvent.button) return;

      const dx = mouseEvent.clientX - current.startX;
      const dy = mouseEvent.clientY - current.startY;
      const distance = Math.hypot(dx, dy);
      const endTime = Date.now();
      const duration = endTime - current.startTime;

      if (distance <= dragMoveThresholdPx && duration <= dragHoldThresholdMs) return;

      suppressClickUntil = endTime + 50;
      emitPayload({
        source,
        timestamp: new Date(current.startTime).toISOString(),
        interaction: {
          action: "drag",
          eventType: "drag",
          target: current.startTargetSnapshot,
          endTarget: targetSnapshot(mouseEvent),
          endTimestamp: new Date(endTime).toISOString(),
          pointer: {
            startX: current.startX,
            startY: current.startY,
            endX: mouseEvent.clientX,
            endY: mouseEvent.clientY,
            button: mouseEvent.button,
          },
          page: { url: location.href, title: document.title },
        },
      });
    },
    { capture: true, passive: true },
  );

  document.addEventListener(
    "click",
    (event) => {
      const mouseEvent = event as MouseEvent;
      if (Date.now() < suppressClickUntil) return;
      send(mouseEvent, {
        action: mouseEvent.detail > 1 ? "doubleClick" : "click",
        eventType: mouseEvent.type,
        pointer: {
          x: mouseEvent.clientX,
          y: mouseEvent.clientY,
          button: mouseEvent.button,
          clickCount: mouseEvent.detail,
        },
      });
    },
    { capture: true, passive: true },
  );

  const modifierKeys = new Set([
    "Shift",
    "Control",
    "Alt",
    "Meta",
    "CapsLock",
    "NumLock",
    "ScrollLock",
  ]);

  document.addEventListener(
    "keydown",
    (event) => {
      const keyboardEvent = event as KeyboardEvent;
      if (keyboardEvent.repeat) return;
      if (modifierKeys.has(keyboardEvent.key)) return;

      const target = keyboardEvent.target;
      const isPrintable = typeof keyboardEvent.key === "string" && keyboardEvent.key.length === 1;
      const hasModifier = keyboardEvent.ctrlKey || keyboardEvent.metaKey || keyboardEvent.altKey;
      const isEditable =
        target instanceof HTMLInputElement ||
        target instanceof HTMLTextAreaElement ||
        (target instanceof HTMLElement && target.isContentEditable);

      if (isPrintable && !hasModifier && isEditable) return;

      send(keyboardEvent, {
        action: "keyPress",
        eventType: keyboardEvent.type,
        keyboard: {
          key: keyboardEvent.key,
          code: keyboardEvent.code,
        },
      });
    },
    { capture: true, passive: true },
  );

  // Per-event emission. Sink-side collapse (logging.utils:collapseActivities)
  // merges consecutive input/change events on the same target into the latest
  // value, so source-level debouncing is unnecessary and only loses precision.
  document.addEventListener(
    "input",
    (event) => {
      send(event, {
        action: "input",
        eventType: "input",
        value: valueSnapshot(event),
      });
    },
    { capture: true, passive: true },
  );

  document.addEventListener(
    "change",
    (event) => {
      send(event, {
        action: "change",
        eventType: "change",
        value: valueSnapshot(event),
      });
    },
    { capture: true, passive: true },
  );

  document.addEventListener(
    "submit",
    (event) => {
      send(event, {
        action: "submit",
        eventType: event.type,
      });
    },
    { capture: true, passive: true },
  );

  // Scroll: throttle to one emission per gesture (trailing edge) since the sink
  // does not currently coalesce scrolls, and raw scroll events fire at frame rate.
  // Scroll does not bubble, so capture it to include focused nested scroll containers.
  let scrollTimer: ReturnType<typeof setTimeout> | null = null;
  const scrollDebounceMs = 200;

  document.addEventListener(
    "scroll",
    () => {
      if (scrollTimer) clearTimeout(scrollTimer);
      scrollTimer = setTimeout(() => {
        scrollTimer = null;
        emitPayload({
          source,
          timestamp: new Date().toISOString(),
          interaction: {
            action: "scroll",
            eventType: "scroll",
            pointer: { x: window.scrollX, y: window.scrollY },
            page: { url: location.href, title: document.title },
          },
        });
      }, scrollDebounceMs);
    },
    { capture: true, passive: true },
  );
}

export function createBrowserInteractionScript(bindingName: string): string {
  return `(() => { const __name = (fn) => fn; (${installBrowserInteractionLogger.toString()})(${JSON.stringify(
    {
      bindingName,
      source: BROWSER_INTERACTION_SOURCE,
      maxTextLength: MAX_BROWSER_INTERACTION_TEXT_LENGTH,
    },
  )}); })();`;
}

import type { BrowserInteractionEvent } from "./types.js";

export const BROWSER_INTERACTION_SOURCE = "steel-browser-interaction";
export const MAX_BROWSER_INTERACTION_TEXT_LENGTH = 256;

const ALLOWED_ACTIONS = new Set([
  "click",
  "doubleClick",
  "keyPress",
  "input",
  "change",
  "submit",
  "scroll",
  "drag",
]);

export interface BrowserInteractionWirePayload {
  source?: unknown;
  timestamp?: unknown;
  interaction?: unknown;
}

export function truncateBrowserInteractionText(value: unknown): string | undefined {
  if (typeof value !== "string") return undefined;
  const normalized = value.replace(/\s+/g, " ").trim();
  if (!normalized) return undefined;
  return normalized.length > MAX_BROWSER_INTERACTION_TEXT_LENGTH
    ? `${normalized.slice(0, MAX_BROWSER_INTERACTION_TEXT_LENGTH - 3)}...`
    : normalized;
}

function optionalNumber(value: unknown): number | undefined {
  return typeof value === "number" && Number.isFinite(value) ? value : undefined;
}

function optionalString(value: unknown): string | undefined {
  return truncateBrowserInteractionText(value);
}

export function toRecord(value: unknown): Record<string, unknown> | undefined {
  return typeof value === "object" && value !== null
    ? (value as Record<string, unknown>)
    : undefined;
}

function sanitizeTarget(value: unknown): BrowserInteractionEvent["interaction"]["target"] {
  const target = toRecord(value);
  if (!target) return undefined;

  const attributes = toRecord(target.attributes);
  const selector = toRecord(target.selector);
  const boundingBox = toRecord(target.boundingBox);

  const x = optionalNumber(boundingBox?.x);
  const y = optionalNumber(boundingBox?.y);
  const width = optionalNumber(boundingBox?.width);
  const height = optionalNumber(boundingBox?.height);

  return {
    tagName: optionalString(target.tagName),
    role: optionalString(target.role),
    accessibleName: optionalString(target.accessibleName),
    text: optionalString(target.text),
    attributes: attributes
      ? {
          id: optionalString(attributes.id),
          name: optionalString(attributes.name),
          type: optionalString(attributes.type),
          href: optionalString(attributes.href),
          ariaLabel: optionalString(attributes.ariaLabel),
          placeholder: optionalString(attributes.placeholder),
          title: optionalString(attributes.title),
          testId: optionalString(attributes.testId),
        }
      : undefined,
    selector: selector
      ? {
          css: optionalString(selector.css),
          id: optionalString(selector.id),
          testId: optionalString(selector.testId),
          name: optionalString(selector.name),
          aria: optionalString(selector.aria),
        }
      : undefined,
    boundingBox:
      x !== undefined && y !== undefined && width !== undefined && height !== undefined
        ? { x, y, width, height }
        : undefined,
  };
}

export function sanitizeInteractionPayload(
  payload: unknown,
): BrowserInteractionEvent["interaction"] | null {
  const parsed = toRecord(payload);
  const interaction = toRecord(parsed?.interaction);
  if (!interaction) return null;

  const action = interaction?.action;
  const eventType = interaction?.eventType;

  if (typeof action !== "string" || !ALLOWED_ACTIONS.has(action)) return null;
  if (typeof eventType !== "string") return null;

  const pointer = toRecord(interaction.pointer);
  const keyboard = toRecord(interaction.keyboard);
  const value = toRecord(interaction.value);
  const page = toRecord(interaction.page);

  const x = optionalNumber(pointer?.x);
  const y = optionalNumber(pointer?.y);
  const startX = optionalNumber(pointer?.startX);
  const startY = optionalNumber(pointer?.startY);
  const endX = optionalNumber(pointer?.endX);
  const endY = optionalNumber(pointer?.endY);
  const hasDragPointer =
    startX !== undefined || startY !== undefined || endX !== undefined || endY !== undefined;

  return {
    action: action as BrowserInteractionEvent["interaction"]["action"],
    eventType,
    target: sanitizeTarget(interaction.target),
    endTarget: action === "drag" ? sanitizeTarget(interaction.endTarget) : undefined,
    endTimestamp:
      action === "drag" && typeof interaction.endTimestamp === "string"
        ? interaction.endTimestamp
        : undefined,
    pointer: hasDragPointer
      ? {
          startX,
          startY,
          endX,
          endY,
          button: optionalNumber(pointer?.button),
        }
      : x !== undefined && y !== undefined
      ? {
          x,
          y,
          button: optionalNumber(pointer?.button),
          clickCount: optionalNumber(pointer?.clickCount),
        }
      : undefined,
    keyboard: keyboard
      ? {
          key: optionalString(keyboard.key),
          code: optionalString(keyboard.code),
        }
      : undefined,
    value: value
      ? {
          inputType: optionalString(value.inputType),
          valueLength: optionalNumber(value.valueLength),
          text: optionalString(value.text),
          redacted: value.redacted === true ? true : undefined,
          checked: typeof value.checked === "boolean" ? value.checked : undefined,
        }
      : undefined,
    page: page
      ? {
          url: optionalString(page.url),
          title: optionalString(page.title),
        }
      : undefined,
  };
}

import type { CDPSession, Page, TargetType } from "puppeteer-core";
import { BrowserEventType } from "../../../types/index.js";
import type { BrowserLogger } from "./browser-logger.js";
import { createBrowserInteractionScript } from "./browser-interaction-script.js";
import {
  BROWSER_INTERACTION_SOURCE,
  sanitizeInteractionPayload,
  toRecord,
} from "./browser-interaction-sanitize.js";

export const BROWSER_INTERACTION_BINDING = "__steelBrowserInteractionLog";
export const BROWSER_INTERACTION_WORLD = "__steel_browser_interactions__";

export async function attachBrowserInteractionEvents(
  session: CDPSession,
  page: Page,
  logger: BrowserLogger,
  targetType: TargetType,
  pageId: string,
): Promise<void> {
  const emitNavigate = (url: string) => {
    logger.record({
      type: BrowserEventType.BrowserInteraction,
      timestamp: new Date().toISOString(),
      pageId,
      targetType,
      interaction: {
        action: "navigate",
        eventType: "framenavigated",
        navigation: { url },
        page: { url },
      },
    });
  };

  page.on("framenavigated", (frame) => {
    if (frame.parentFrame()) return;
    emitNavigate(frame.url());
  });

  emitNavigate(page.url());

  session.on("Runtime.bindingCalled", (event: any) => {
    if (event?.name !== BROWSER_INTERACTION_BINDING || typeof event.payload !== "string") return;

    let parsed: unknown;
    try {
      parsed = JSON.parse(event.payload);
    } catch {
      return;
    }

    const payload = toRecord(parsed);
    if (payload?.source !== BROWSER_INTERACTION_SOURCE) return;

    const interaction = sanitizeInteractionPayload(payload);
    if (!interaction) return;

    logger.record({
      type: BrowserEventType.BrowserInteraction,
      timestamp:
        typeof payload.timestamp === "string" ? payload.timestamp : new Date().toISOString(),
      pageId,
      targetType,
      interaction,
    });
  });

  try {
    await session.send("Runtime.addBinding" as any, {
      name: BROWSER_INTERACTION_BINDING,
      executionContextName: BROWSER_INTERACTION_WORLD,
    });
  } catch {
    // Interaction logging is best-effort and should not block target instrumentation.
    return;
  }

  const source = createBrowserInteractionScript(BROWSER_INTERACTION_BINDING);
  try {
    await session.send("Page.addScriptToEvaluateOnNewDocument" as any, {
      source,
      worldName: BROWSER_INTERACTION_WORLD,
      runImmediately: true,
    });
  } catch {
    try {
      await session.send("Page.addScriptToEvaluateOnNewDocument" as any, {
        source,
        worldName: BROWSER_INTERACTION_WORLD,
      });
    } catch {
      // Older browsers may not support isolated-world script injection.
    }
  }
}

